INSERT INTO REFDATA.SIGNAL_TYPE (
    NAME, DISPLAY_NAME, FUNC_NAME_BAND, FUNC_NAME_BOUNDED, DESCRIPTION, USER_ID, UPDATED_AT
)
SELECT 'momentum_long', 'Momentum (long only)',
       'momentum_band_signal_long_only', 'momentum_bounded_signal_long_only',
       'Long or flat — never short', 'alfcheun', NOW() AT TIME ZONE 'UTC'
 WHERE NOT EXISTS (
       SELECT 1 FROM REFDATA.SIGNAL_TYPE WHERE NAME = 'momentum_long'
 );

